import { useId, useRef } from "react";
import type { KeyboardEvent } from "react";
import "./SegmentedControl.css";

export interface SegmentedOption<T extends string> {
  value: T;
  label: string;
}

export interface SegmentedControlProps<T extends string> {
  label: string;
  options: readonly SegmentedOption<T>[];
  value: T;
  onChange: (value: T) => void;
}

export function SegmentedControl<T extends string>({
  label,
  options,
  value,
  onChange,
}: SegmentedControlProps<T>) {
  const labelId = useId();
  const buttonRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const checkedIndex = options.findIndex((option) => option.value === value);
  // Roving tabindex: only one radio is in the Tab order. If no option matches
  // the value, the first option is the entry point.
  const tabStopIndex = checkedIndex === -1 ? 0 : checkedIndex;

  function select(index: number) {
    const option = options[index];
    if (!option) {
      return;
    }
    buttonRefs.current[index]?.focus();
    onChange(option.value);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = options.length - 1;
    let next: number | null = null;

    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        next = index === last ? 0 : index + 1;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        next = index === 0 ? last : index - 1;
        break;
      case "Home":
        next = 0;
        break;
      case "End":
        next = last;
        break;
      default:
        return;
    }

    event.preventDefault();
    select(next);
  }

  return (
    <div className="segmented">
      <span id={labelId} className="segmented__label">
        {label}
      </span>
      <div role="radiogroup" aria-labelledby={labelId} className="segmented__track">
        {options.map((option, index) => {
          const checked = index === checkedIndex;
          return (
            <button
              key={option.value}
              ref={(element) => {
                buttonRefs.current[index] = element;
              }}
              type="button"
              role="radio"
              aria-checked={checked}
              tabIndex={index === tabStopIndex ? 0 : -1}
              className="segmented__option"
              onClick={() => onChange(option.value)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}
