.segmented {
  display: inline-flex;
  flex-direction: column;
  gap: 0.4rem;
  color: var(--ink);
  font: inherit;
}

.segmented__label {
  color: var(--muted);
  font-size: clamp(0.75rem, 0.7rem + 0.2vw, 0.875rem);
  letter-spacing: 0.02em;
}

.segmented__track {
  display: inline-flex;
  align-items: stretch;
  gap: 0.2rem;
  padding: 0.2rem;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: var(--code-bg);
}

.segmented__option {
  appearance: none;
  margin: 0;
  padding: 0.45em 1.1em;
  border: 1px solid transparent;
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.8rem, 0.75rem + 0.25vw, 0.95rem);
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease;
}

.segmented__option:hover:not([aria-checked="true"]) {
  background: var(--myelin-wash);
}

.segmented__option[aria-checked="true"] {
  background: var(--myelin);
  color: var(--slide);
  border-color: var(--myelin);
}

.segmented__option[aria-checked="true"]:focus-visible {
  border-color: var(--myelin);
}

:root[data-motion="reduce"] .segmented__option {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .segmented__option {
    transition: none;
  }
}
